// plainc-ecu -- Case 1: a developer's PLAIN C control model (auto-generated by Simulink
// Embedded Coder / dSPACE TargetLink) plugged into libsils_vecu (Option 2 plant coupling).
//
// The model (src/speedctl.c) is SDK-agnostic C and is never edited; src/plainc_behavior.hpp
// adapts it to IVehicleBehavior; sils::RunVehicleProbe owns everything else (DDS, channel-map
// reader/writer binding, tick loop, trace, teardown). This is the counterpart of steer-ecu,
// differing only in WHERE the control math comes from: an external generated C unit rather
// than a hand-written C++ behavior. See README.md for the three plug-in cases.

#include <memory>

#include "config.hpp"           // sils::ConfigFromEnv / GetEnvDoubleOr
#include "plainc_behavior.hpp"
#include "vehicle_run.hpp"      // sils::RunVehicleProbe

int main() {
    const sils::ProbeConfig cfg = sils::ConfigFromEnv();

    auto behavior = std::make_unique<PlainCBehavior>();
    // Map the SDK's reused control knobs onto the generated model's calibrations.
    behavior->set_v_setpoint(sils::GetEnvDoubleOr("SILS_CTRL_SETPOINT", 10.0));
    behavior->set_kp_speed(cfg.ctrl_kp);

    return sils::RunVehicleProbe(cfg, std::move(behavior));
}
